export const catalog=[['조선미녀','맑은쌀 선크림 SPF50+','50ml','선케어','Beauty of Joseon',14500,'#e8ddcc'],['COSRX','스네일 96 뮤신 에센스','100ml','에센스','코스알엑스 Snail',16800,'#dfcf9b'],['아누아','어성초 77 수딩 토너','250ml','토너','Anua',18900,'#c9d6bb'],['라운드랩','1025 독도 토너','200ml','토너','Round Lab',13500,'#c4d9e6'],['토리든','다이브인 히알루론산 세럼','50ml','에센스','Torriden',17900,'#bbd9df'],['스킨1004','마다가스카르 센텔라 앰플','55ml','에센스','SKIN1004',15900,'#e7c399'],['라네즈','립 슬리핑 마스크 베리','20g','립케어','Laneige',16500,'#edb5bd'],['이니스프리','레티놀 시카 흔적 앰플','30ml','에센스','Innisfree',24800,'#bbceb3'],['닥터자르트','시카페어 크림','50ml','크림','Dr Jart',27900,'#bdd0b8'],['에스트라','아토베리어365 크림','80ml','크림','Aestura',23900,'#c4d1e4']].map((a,i)=>({id:String(i+1),brand:a[0],name:a[1],size:a[2],category:a[3],keywords:a[4],base:a[5],color:a[6],history:Array.from({length:30},(_,d)=>Math.round((a[5]+(29-d)*90+Math.sin(d*.8+i)*900)/100)*100),offers:[{name:'뷰티마켓 A',price:a[5],shipping:2500,days:'2–3일'},{name:'브랜드몰 B',price:a[5]+1200,shipping:0,days:'1–2일'},{name:'코스메틱 C',price:a[5]-500,shipping:3000,days:'3–4일'}]}));
export const search=(q,c='전체')=>catalog.filter(p=>(c==='전체'||p.category===c)&&`${p.brand} ${p.name} ${p.keywords}`.toLowerCase().includes(q.trim().toLowerCase()));
export const offersFor=(p,sim)=>p.offers.map((o,i)=>({...o,price:i===1&&sim!=null?sim:o.price,total:(i===1&&sim!=null?sim:o.price)+o.shipping})).sort((a,b)=>a.total-b.total);
export const alertState=(target,current)=>target==null?'미설정':current<=target?'목표가 도달':'기다리는 중';
export const validPrice=v=>/^\d+$/.test(String(v))&&Number(v)>0&&Number(v)<=10000000;
export function readState(storage){try{const v=JSON.parse(storage.getItem('pricepilot-v1'));return {favorites:Array.isArray(v?.favorites)?v.favorites.filter(x=>catalog.some(p=>p.id===x)):[],targets:Object.fromEntries(Object.entries(v?.targets||{}).filter(([id,n])=>catalog.some(p=>p.id===id)&&validPrice(n)))}}catch{return {favorites:[],targets:{}}}}
export function toggleFavorite(s,id){s.favorites=s.favorites.includes(id)?s.favorites.filter(x=>x!==id):[...s.favorites,id];return s;}
